query MyQuery($owner: String!, $repository: String!) {
    repository(owner: $owner, name: $repository) {
      issues(first: 100, states: [OPEN], orderBy:  {field: UPDATED_AT, direction: DESC}) {
        totalCount
        nodes {
          assignees(first: 100) {
            nodes {
              login
            }
          }
          body
          bodyHTML
          bodyText
          editor {
            url
            login
            avatarUrl
          }
          number
          id
          title
          url
          createdAt
          updatedAt   
          author {
            url
            login
            avatarUrl
          }
          comments(first: 100) {
            nodes {
              body
              author {
                login
              }
              editor {
                url
                login
                avatarUrl
              }
              bodyText
              createdAt
              updatedAt
            }
          }
        }
      }
    } 
  }
